import React from "react";
import { Route, Redirect } from "react-router-dom";
import { useAuthState } from "react-firebase-hooks/auth"; // optional hook for easier state management
import { auth } from "../firebase"; // Import your Firebase auth

const ProtectedRoute = ({ component: Component, ...rest }) => {
  const [user, loading, error] = useAuthState(auth); // Check user state

  if (loading) {
    return <div>Loading...</div>; // Show loading spinner or message
  }

  return (
    <Route
      {...rest}
      render={(props) =>
        user ? (
          <Component {...props} /> // If the user is logged in, render the protected page
        ) : (
          <Redirect to="/auth/login" /> // Redirect to login if not logged in
        )
      }
    />
  );
};

export default ProtectedRoute;
